import typing


def first(values: list[str]) -> typing.Optional[str]:
    return values[0] if values else None

def ratio(part: int, whole: int) -> float:
    if whole == 0:
        raise ValueError("whole が0")
    return part / whole

def safe_metrics(where: Layout) -> str:
    try:
        return metrics(where)
    except Exception:
        return ""

