def _has_long_goal(plan: contracts.Plan, _profile: profile.Profile) -> bool:
    return len(plan.goal) > 200


H1_RULES = (*H1_RULES, PlanRule("h1_long_goal", "ゴールが長い", _has_long_goal))

def _is_human_only(plan: contracts.Plan, _profile: profile.Profile) -> bool:
    return all(item.check == contracts.HUMAN for item in plan.criteria)


H1_RULES = (*H1_RULES, PlanRule("h1_human_criteria", "受け入れ条件が全部、人が確かめるものである", _is_human_only))

def review_tally(where: Layout, run_id: str, now: str) -> str:
    events = workspace.load_trail(where, run_id)
    return f"{now} {len(events)}"

